from itertools import product

def transform(grid):
    pts={(r,c) for r,row in enumerate(grid) for c,v in enumerate(row) if v==8}
    h,w=len(grid),len(grid[0]) if grid else 0
    tiles=[]
    for r in range(h-1):
      for c in range(w-1):
        box={(r,c),(r,c+1),(r+1,c),(r+1,c+1)}
        if box<=pts: tiles.append((box,1))
        for missing,col in [((r,c),2),((r+1,c),3),((r,c+1),4),((r+1,c+1),5)]:
          s=box-{missing}
          if s<=pts: tiles.append((s,col))
    bypt={p:[] for p in pts}
    for s,col in tiles:
      for p in s: bypt[p].append((s,col))
    def search(rem,assigned):
      if not rem:return assigned
      p=min(rem,key=lambda x:sum(s<=rem for s,col in bypt[x]))
      for s,col in bypt[p]:
        if s<=rem:
          ans=search(rem-s,assigned+[(s,col)])
          if ans is not None:return ans
      return None
    sol=search(pts,[])
    out=[[0]*w for _ in range(h)]
    if sol:
      for s,col in sol:
       for r,c in s:out[r][c]=col
    return out

