source='''def transform(grid):
    pts = {(r, c) for r, row in enumerate(grid) for c, value in enumerate(row) if value == 8}
    h, w = len(grid), len(grid[0]) if grid else 0
    tiles = []
    for r in range(h - 1):
        for c in range(w - 1):
            box = {(r, c), (r, c + 1), (r + 1, c), (r + 1, c + 1)}
            if box <= pts:
                tiles.append((box, 1))
            for missing, color in (((r, c), 2), ((r + 1, c), 3), ((r, c + 1), 4), ((r + 1, c + 1), 5)):
                shape = box - {missing}
                if shape <= pts:
                    tiles.append((shape, color))
    by_point = {point: [] for point in pts}
    for shape, color in tiles:
        for point in shape:
            by_point[point].append((shape, color))
    def cover(remaining, chosen):
        if not remaining:
            return chosen
        point = min(remaining, key=lambda p: sum(shape <= remaining for shape, _ in by_point[p]))
        for shape, color in by_point[point]:
            if shape <= remaining:
                result = cover(remaining - shape, chosen + [(shape, color)])
                if result is not None:
                    return result
        return None
    solution = cover(pts, [])
    output = [[0 for _ in range(w)] for _ in range(h)]
    if solution is not None:
        for shape, color in solution:
            for r, c in shape:
                output[r][c] = color
    return output
'''
